#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long r;
    long long m;
    cin >> n >> r >> m;
    long long s;
    long long t;
    cin >> s >> t;
    vector<vector<long long>> pairs(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> pairs[i][j];
        }
    }

    vector<vector<int>> busesAt(n + 1), stopsOf(r + 1);
    for (const vector<long long>& p : pairs) {
        busesAt[p[1]].push_back((int)p[0]);
        stopsOf[p[0]].push_back((int)p[1]);
    }
    long long answer = -1;
    if (s == t) {
        answer = 0;
    } else {
        vector<char> seenBus(r + 1, 0), seenStop(n + 1, 0);
        seenStop[s] = 1;
        vector<int> layer = {(int)s};
        long long rides = 0;
        while (!layer.empty() && answer < 0) {
            rides++;
            vector<int> next;
            for (int x : layer) {
                for (int b : busesAt[x]) {
                    if (seenBus[b]) continue;
                    seenBus[b] = 1;
                    for (int y : stopsOf[b]) {
                        if (y == t) answer = rides;
                        if (!seenStop[y]) {
                            seenStop[y] = 1;
                            next.push_back(y);
                        }
                    }
                }
            }
            layer = next;
        }
    }
    cout << answer << "\n";

    return 0;
}

